    $('#sint-rep').onclick=()=>{const n=al.filter(x=>x.sintese&&x.sintese[per]).length;if(!n)return toast('Nenhuma síntese foi editada à mão','aviso');if(!confirm('Substituir as '+n+' sínteses editadas à mão pelo texto automático?'))return;al.forEach(x=>{if(x.sintese)delete x.sintese[per]});save();toast(n+' sínteses atualizadas','ok');draw()};
